document.addEventListener("click",e=>{const j=e.target.closest("[data-setjump]");if(!j)return;const el=document.getElementById(j.dataset.setjump);if(el)el.scrollIntoView({behavior:"smooth",block:"start"})});
document.addEventListener("click",e=>{const t=e.target.closest("button");if(!t||view!=="settings")return;
  const val=sel=>{const el=document.querySelector(sel);const v=(el?.value||"").trim();return v};
  if(t.id==="g-add"){const n=val("#g-new");if(!n){toast("Type a group name first.");return}if(GROUPS.some(g=>g.name.toLowerCase()===n.toLowerCase())){toast("That group already exists.");return}GROUPS.push({name:n,room:"",educator:""});saveProgram();renderSettings();return}
  if(t.dataset.gdel!=null){GROUPS.splice(+t.dataset.gdel,1);saveProgram();renderSettings();return}
  if(t.id==="p-add"){spaceAdd(val("#p-new"));return}
  if(t.id==="c-add"){const n=val("#c-new").replace(/\s+class$/i,"");if(!n){toast("Type the Class's name first.");return}if(CLASSROOMS.some(r=>r.toLowerCase()===n.toLowerCase())){toast("That Class is already on the list.");return}CLASSROOMS=[...CLASSROOMS,n];saveProgram();renderSettings();return}
  if(t.dataset.cdel!=null){const r=CLASSROOMS[+t.dataset.cdel];const kids=[...children.values()].filter(c=>c.classroom===r&&kidAt(c)).length,gs=GROUPS.filter(g=>g.room===r).length;
    if(kids||gs){toast(`${r} still has ${kids?kids+(kids===1?" child":" children"):""}${kids&&gs?" and ":""}${gs?gs+(gs===1?" small group":" small groups"):""}. Move them first.`);return}
    CLASSROOMS=CLASSROOMS.filter(x=>x!==r);saveProgram();renderSettings();return}
  if(t.id==="a-add"){const n=val("#a-new");if(n&&!AREAS.some(x=>x.toLowerCase()===n.toLowerCase())){AREAS.push(n);saveProgram()}renderSettings();return}
  if(t.dataset.adel!=null){AREAS.splice(+t.dataset.adel,1);saveProgram();renderSettings();return}
  if(t.id==="l-add"){const n=val("#l-new");if(n&&!LANGUAGES.some(x=>x.toLowerCase()===n.toLowerCase())){LANGUAGES.push(n);saveProgram()}renderSettings();return}
  if(t.dataset.ldel!=null){LANGUAGES.splice(+t.dataset.ldel,1);saveProgram();renderSettings();return}
  if(t.dataset.psd!=null){PRINT.schoolDocs=t.dataset.psd==="1";saveProgram();renderSettings();return}
  if(t.dataset.psr!=null){PRINT.schoolRecords=t.dataset.psr==="1";saveProgram();renderSettings();return}
  if(t.dataset.pnm){PRINT.names=t.dataset.pnm;saveProgram();renderSettings();return}
  if(t.dataset.pby){PRINT.by=t.dataset.pby==="1";saveProgram();renderSettings();return}
  if(t.dataset.proofsave){if(!isDirector())return;PROOF_SAVE=t.dataset.proofsave==="1";proofBtn();saveProgram();renderSettings();return}
  if(t.dataset.mdel){const [c,i]=t.dataset.mdel.split("|");MATERIALS[c].splice(+i,1);saveProgram();renderSettings();return}
  if(t.dataset.madd){const c=t.dataset.madd;const n=(document.querySelector(`[data-madd-in="${CSS.escape(c)}"]`)?.value||"").trim();if(n&&!MATERIALS[c].includes(n)){MATERIALS[c].push(n);saveProgram()}renderSettings();return}
  if(t.dataset.mcatdel){delete MATERIALS[t.dataset.mcatdel];saveProgram();renderSettings();return}
  if(t.id==="mc-add"){const n=val("#mc-new");if(n&&!MATERIALS[n]){MATERIALS[n]=[];saveProgram()}renderSettings();return}
  if(t.id==="prog-reset"){$("#resetwrap").innerHTML=`<span class="confirm">Replace all lists with the originals? <button class="btn warn small" id="prog-reset-yes">Restore</button><button class="linkbtn" id="prog-reset-no">Keep mine</button></span>`;return}
  if(t.id==="prog-reset-no"){renderSettings();return}
  if(t.id==="prog-reset-yes"){const d0=JSON.parse(JSON.stringify(PDEF));
    // the Classes and small groups are the school's own lists and the spaces are the calendar's, so a reset keeps them
    d0.classrooms=CLASSROOMS.slice();d0.groups=JSON.parse(JSON.stringify(GROUPS));delete d0.places;applyProgram(Object.assign({},PROGRAM_DOC,d0));saveProgram();renderSettings();toast("Original lists restored.");return}
});
document.addEventListener("change",e=>{if(view!=="settings")return;const t=e.target;
  if(t.dataset.gname!=null){const n=t.value.trim();if(n){GROUPS[+t.dataset.gname].name=n;saveProgram()}return}
  if(t.id==="gg-name"){const n=t.value.trim().slice(0,40);if(n){PROGRAM_DOC=Object.assign({},PROGRAM_DOC,{gardenGroup:{name:n}});saveProgram()}return}
  if(t.dataset.groom!=null){GROUPS[+t.dataset.groom].room=t.value;saveProgram();return}
  if(t.dataset.ged!=null){GROUPS[+t.dataset.ged].educator=t.value;saveProgram();return}
});
document.addEventListener("keydown",e=>{if(view!=="settings"||e.key!=="Enter")return;const t=e.target;
  const map={"g-new":"#g-add","p-new":"#p-add","mc-new":"#mc-add"};
  if(map[t.id]){e.preventDefault();$(map[t.id]).click()}
  if(t.dataset.maddIn!=null){e.preventDefault();document.querySelector(`[data-madd="${CSS.escape(t.dataset.maddIn)}"]`).click()}
});


window.TreeLazy_settings=true;
